# payload_safety.py - Check decrypted text payloads for unsafe content\n\nimport re\nfrom typing import List, Tuple\n\n# ---------------------------------------------------------------------------\n# Unsafe content patterns (example regexes; adapt to your policy)\n# ---------------------------------------------------------------------------\n\n# Simple patterns for demonstration – in production use more robust classifiers\nUNSAFE_PATTERNS = [\n    re.compile(r\"credit card\\s*:\\s*\\d{4}\\s*\\d{4}\\s*\\d{4}\\s*\\d{4}\", re.IGNORECASE),\n    re.compile(r\"social security\\s*:\\s*\\d{3}[- ]?\\d{2}[- ]?\\d{4}\", re.IGNORECASE),\n    re.compile(r\"password\\s*[:=]\\s*\\S+\", re.IGNORECASE),\n    re.compile(r\"ssh\\s*key\\s*:[\\s\\S]*?(ssh[-_]rsa|ssh[-_]ed25519)[\\s\\S]*?public key\", re.IGNORECASE),\n]\n\n# ---------------------------------------------------------------------------\n# Detection helpers\n# ---------------------------------------------------------------------------\n\ndef contains_unsafe(text: str) -> bool:\n    \"\"\"Return True if any unsafe pattern matches the plaintext.\"\"\"\n    for pattern in UNSAFE_PATTERNS:\n        if pattern.search(text):\n            return True\n    return False\n\ndef scan_payload(payload: str) -> List[Tuple[str, str]]:\n    \"\"\"Return a list of (pattern_description, matched_snippet) for each unsafe match.\n\n    Example output: [ ('Credit Card', '4111 1111 1111 1111'), ... ]\n    \"\"\"\n    findings = []\n    for pattern in UNSAFE_PATTERNS:\n        for match in pattern.finditer(payload):\n            snippet = match.group(0)\n            # Provide a simple label based on the regex\n            label = pattern.pattern.split('\\')[1]  # crude extraction\n            findings.append((label, snippet))\n    return findings\n\n# ---------------------------------------------------------------------------\n# Example usage (CLI)\n# ---------------------------------------------------------------------------\n\ndef main():\n    sample = \"This is a secret. Credit card: 4111 1111 1111 1111\"\n    safe = not contains_unsafe(sample)\n    print(\"Safe?\", safe)\n    if not safe:\n        findings = scan_payload(sample)\n        print(\"Unsafe findings:\")\n        for label, snippet in findings:\n            print(f\"  {label}: {snippet}\")\n\nif __name__ == '__main__':\n    main()\n